import{_ as o,o as t,c,ag as i}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-09-22（地球科学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/earth-science/science-daily-2026-09-22.md","filePath":"topics/earth-science/science-daily-2026-09-22.md"}'),a={name:"topics/earth-science/science-daily-2026-09-22.md"};function n(s,e,r,l,d,u){return t(),c("div",null,[...e[0]||(e[0]=[i('<h1 id="科学日报-·-2026-09-22-地球科学" tabindex="-1">科学日报 · 2026-09-22（地球科学） <a class="header-anchor" href="#科学日报-·-2026-09-22-地球科学" aria-label="Permalink to &quot;科学日报 · 2026-09-22（地球科学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-22.md</code> — 第29期</p></blockquote><hr><h2 id="地下核试验的多年余震-万塔山断层被-复活-science" tabindex="-1">地下核试验的多年余震：万塔山断层被&quot;复活&quot;（Science） <a class="header-anchor" href="#地下核试验的多年余震-万塔山断层被-复活-science" aria-label="Permalink to &quot;地下核试验的多年余震：万塔山断层被&quot;复活&quot;（Science）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-22.md</code> ｜ DOI: 10.1126/science.adx5917</p></blockquote><ul><li>常识预期：地下核爆炸只产生<strong>短寿命</strong>地震序列，试验停止后迅速衰减。</li><li>观测（朝鲜丰溪里万塔山，2017 年最后一次大当量爆炸之后）：地震活动<strong>持续并增强</strong>多年，从弥散活动演化为沿断裂控制结构的<strong>空间有序分布</strong>。</li><li>数据：17 年连续波形；地震活动逐步增加 + <strong>浅部断层延迟复活</strong>；地震丛集在不对称地形之下 ⇒ 临界应力地壳体积内的渐进应力重分布。</li><li>洞察：这说明&quot;爆炸→衰减&quot;不是普适规律，在特定地质条件下核试验可以驱动<strong>多年尺度</strong>的断层复活。与 2026-09-16 期&quot;日本地震黏土层晚了 13 年&quot;（见 <code>2026-q3.md</code>）同族：<strong>地壳的响应时间常数远比人类直觉长</strong>。也提示核试验监测不能只看爆炸当量窗口，还要看延迟触发的构造响应。</li></ul><hr><h2 id="保护现存热带森林比事后恢复更划算-但组合干预才最关键-science" tabindex="-1">保护现存热带森林比事后恢复更划算，但组合干预才最关键（Science） <a class="header-anchor" href="#保护现存热带森林比事后恢复更划算-但组合干预才最关键-science" aria-label="Permalink to &quot;保护现存热带森林比事后恢复更划算，但组合干预才最关键（Science）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-22.md</code> ｜ DOI: 10.1126/science.adx9928</p></blockquote><ul><li>三类干预：阻止毁林（avoidance）、恢复（restoration）、以及关注度最低的<strong>避免森林干扰</strong>。</li><li>方法：巴西亚马逊毁林前沿，深入野外评估 + 高分辨率遥感，比较观测结果与反事实结果，量化生物多样性收益、碳收益与成本。</li><li>结果：<strong>避免干扰收益最大且比恢复更具成本效益</strong>，对一系列收益/成本假设稳健；但<strong>组合干预总收益最大</strong>，对扭转生物多样性与碳损失不可或缺。</li><li>洞察：这是&quot;<strong>事前预防 &gt; 事后修复</strong>&quot;在一个可量化场景里的实证版本，同时给出边界条件——单靠保护无法把已损失的部分补回来。与库内&quot;汇被漏算时源会被高估&quot;（09-21 LGM 甲烷）互为索引维度问题：同一片林子，按&quot;存量保护&quot;还是&quot;流量恢复&quot;记账，结论会反向。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/earth-science/index.md</code> ｜ 第29期 科学板块</p></blockquote><p>关键词：核试验、万塔山、断层复活、诱发地震、应力重分布、热带森林、亚马逊、保护vs恢复、成本效益、生物多样性 关联：<code>topics/earth-science/science-daily-2026-09-21.md</code>（汇/源索引维度）、<code>topics/earth-science/2026-q3.md</code>（日本地震黏土层延迟 13 年）、<code>topics/real-estate/</code>（事前预防 vs 事后修复的成本结构）</p>',13)])])}const h=o(a,[["render",n]]);export{p as __pageData,h as default};
